    function automatic [127:0] read_w0(input [63:0] addr);
        integer i;
        begin
            read_w0 = 128'd0;
            for (i = 0; i < AXI_BYTES; i = i + 1)
                if ((addr + i) < MEM_BYTES) read_w0[i*8 +: 8] = mem_w0[addr + i];
        end
    endfunction

    function automatic [127:0] read_w1(input [63:0] addr);
        integer i;
        begin
            read_w1 = 128'd0;
            for (i = 0; i < AXI_BYTES; i = i + 1)
                if ((addr + i) < MEM_BYTES) read_w1[i*8 +: 8] = mem_w1[addr + i];
        end
    endfunction

    function automatic [127:0] read_act(input [63:0] addr);
        integer i;
        begin
            read_act = 128'd0;
            for (i = 0; i < AXI_BYTES; i = i + 1)
                if ((addr + i) < MEM_BYTES) read_act[i*8 +: 8] = mem_act[addr + i];
        end
    endfunction

    function automatic [127:0] read_out(input [63:0] addr);
        integer i;
        begin
            read_out = 128'd0;
            for (i = 0; i < AXI_BYTES; i = i + 1)
                if ((addr + i) < MEM_BYTES) read_out[i*8 +: 8] = mem_out[addr + i];
        end
    endfunction

    function automatic void write_w0(input [63:0] addr, input [127:0] data, input [15:0] strb);
        integer i;
        begin
            for (i = 0; i < AXI_BYTES; i = i + 1)
                if (strb[i] && (addr + i) < MEM_BYTES) mem_w0[addr + i] = data[i*8 +: 8];
        end
    endfunction

    function automatic void write_w1(input [63:0] addr, input [127:0] data, input [15:0] strb);
        integer i;
        begin
            for (i = 0; i < AXI_BYTES; i = i + 1)
                if (strb[i] && (addr + i) < MEM_BYTES) mem_w1[addr + i] = data[i*8 +: 8];
        end
    endfunction

    function automatic void write_act(input [63:0] addr, input [127:0] data, input [15:0] strb);
        integer i;
