    function automatic integer align_up(input integer value, input integer align);
        begin
            align_up = ((value + align - 1) / align) * align;
        end
    endfunction

    function automatic integer div_ceil(input integer value, input integer divisor);
        begin
            div_ceil = (value + divisor - 1) / divisor;
        end
    endfunction

    function automatic integer act_value(input integer m, input integer k);
        begin
            act_value = ((m * 5 + k * 3) % 13) - 6;
        end
    endfunction

    function automatic integer act_exp_value(input integer m, input integer g, input bit varied);
        begin
            act_exp_value = varied ? (((m + g * 3) % 3) - 1) : 0;
        end
    endfunction

    function automatic integer weight_value(input integer seed, input integer k, input integer n);
        begin
            weight_value = ((seed + k * 7 + n * 5) % 11) - 5;
        end
    endfunction

    function automatic integer sat_i64(input longint signed v);
        begin
            if (v > 2147483647) sat_i64 = 2147483647;
            else if (v < (-2147483647 - 1)) sat_i64 = (-2147483647 - 1);
            else sat_i64 = $signed(v[31:0]);
        end
    endfunction

    function automatic integer sat_i128(input logic signed [127:0] v);
        begin
            if (v > 128'sd2147483647) sat_i128 = 2147483647;
            else if (v < -(128'sd2147483648)) sat_i128 = (-2147483647 - 1);
            else sat_i128 = $signed(v[31:0]);
        end
    endfunction

    function automatic integer sat_add_i32(input integer a, input integer b);
        longint signed wide;
        begin
            wide = a;
            wide = wide + b;
            sat_add_i32 = sat_i64(wide);
        end
    endfunction

    function automatic integer shift_apply(input integer x, input integer e);
        integer shift;
        integer rs;
        longint signed wide;
        longint signed half;
        begin
            shift = e + OUT_FRAC;
            wide = x;
            if (shift >= 0) begin
                if (shift >= 31) begin
                    if (x > 0) shift_apply = 2147483647;
                    else if (x < 0) shift_apply = (-2147483647 - 1);
                    else shift_apply = 0;
                end else begin
                    wide = wide <<< shift;
                    shift_apply = sat_i64(wide);
                end
            end else begin
                rs = -shift;
                if (rs >= 63) begin
                    wide = 0;
                end else begin
                    half = 64'sd1 <<< (rs - 1);
                    wide = (wide >= 0) ? (wide + half) : (wide - half);
                    wide = wide >>> rs;
                end
                shift_apply = sat_i64(wide);
            end
        end
    endfunction

    function automatic integer hard_silu(input integer x);
        integer xp;
        integer cl;
        logic signed [127:0] p;
        begin
            xp = x + (3 <<< OUT_FRAC);
            cl = (xp < 0) ? 0 : ((xp > (6 <<< OUT_FRAC)) ? (6 <<< OUT_FRAC) : xp);
            p = x;
            p = p * cl;
            hard_silu = sat_i128((p * 128'sd2796203) >>> 44);
        end
    endfunction

    function automatic integer hard_gelu(input integer x);
        integer xp;
        integer cl;
        logic signed [127:0] p;
        begin
            xp = x + (3 <<< (OUT_FRAC - 1));
            cl = (xp < 0) ? 0 : ((xp > (3 <<< OUT_FRAC)) ? (3 <<< OUT_FRAC) : xp);
            p = x;
            p = p * cl;
            hard_gelu = sat_i128((p * 128'sd5592405) >>> 44);
        end
    endfunction

    function automatic integer round_mul_q20(input integer a, input integer b);
        longint signed p;
        longint signed half;
        begin
            p = a;
            p = p * b;
            half = 64'sd1 <<< (OUT_FRAC - 1);
            p = (p >= 0) ? (p + half) : (p - half);
            round_mul_q20 = sat_i64(p >>> OUT_FRAC);
        end
    endfunction

    function automatic integer choose_pot_exp_q20(input integer max_abs);
        integer selected_shift;
        integer shift;
        bit found;
        bit fits;
        longint signed scaled;
        begin
            if (max_abs <= 0) begin
                choose_pot_exp_q20 = 0;
            end else begin
                selected_shift = OUT_FRAC;
                found = 1'b0;
                for (shift = -10; shift <= 50; shift = shift + 1) begin
                    if (shift >= 0) begin
                        fits = (shift >= 31) || (max_abs <= (64'sd127 <<< shift));
                    end else begin
                        scaled = max_abs;
                        scaled = scaled <<< (-shift);
                        fits = (scaled <= 127);
                    end
                    if (fits && !found) begin
                        selected_shift = shift;
                        found = 1'b1;
                    end
                end
                choose_pot_exp_q20 = selected_shift - OUT_FRAC;
                if (choose_pot_exp_q20 < -30) choose_pot_exp_q20 = -30;
                if (choose_pot_exp_q20 > 30) choose_pot_exp_q20 = 30;
            end
        end
    endfunction

    function automatic integer quantize_q20_exp(input integer x, input integer exp);
        integer shift;
        integer q;
        longint signed wide;
        integer half;
        begin
            shift = exp + OUT_FRAC;
            if (shift >= 0) begin
                if (shift >= 31) q = 0;
                else if (shift == 0) q = x;
                else begin
                    half = 1 <<< (shift - 1);
                    q = (x >= 0) ? ((x + half) >>> shift) : ((x - half) >>> shift);
                end
            end else begin
                wide = x;
                wide = wide <<< (-shift);
                q = sat_i64(wide);
            end
            if (q > 127) q = 127;
            if (q < -127) q = -127;
            quantize_q20_exp = q;
        end
    endfunction

    function automatic integer r_i32_out(input integer addr);
        logic [31:0] v;
        begin
            v = {mem_out[addr + 3], mem_out[addr + 2], mem_out[addr + 1], mem_out[addr + 0]};
            r_i32_out = $signed(v);
        end
    endfunction

    task automatic clear_memories;
        integer i;
        begin
            for (i = 0; i < MEM_BYTES; i = i + 1) begin
                mem_w0[i] = 8'd0;
                mem_w1[i] = 8'd0;
                mem_act[i] = 8'd0;
                mem_out[i] = 8'd0;
            end
        end
    endtask

    task automatic wb_act(input integer off, input integer value);
        begin
            if (off >= 0 && off < MEM_BYTES) mem_act[off] = value[7:0];
        end
    endtask

    task automatic wb_weight(input integer port, input integer off, input integer value);
        begin
            if (off >= 0 && off < MEM_BYTES) begin
                if (port == 0) mem_w0[off] = value[7:0];
                else           mem_w1[off] = value[7:0];
            end
        end
    endtask

    task automatic wr32(input integer off, input [31:0] value);
        begin
            wb_act(off + 0, value[7:0]);
            wb_act(off + 1, value[15:8]);
            wb_act(off + 2, value[23:16]);
            wb_act(off + 3, value[31:24]);
        end
    endtask

    task automatic wr64(input integer off, input [63:0] value);
        begin
            wr32(off, value[31:0]);
            wr32(off + 4, value[63:32]);
        end
    endtask

    task automatic fill_act(input integer q_off, input integer s_off,
                            input integer rows, input integer K,
                            input integer row_stride, input integer scale_stride,
                            input bit varied_exp);
        integer m;
        integer k;
        integer g;
        integer groups;
        begin
            groups = K / GROUP;
            for (m = 0; m < rows; m = m + 1) begin
                for (k = 0; k < K; k = k + 1)
                    wb_act(q_off + m * row_stride + k, act_value(m, k));
                for (g = 0; g < groups; g = g + 1)
                    wb_act(s_off + m * scale_stride + g, act_exp_value(m, g, varied_exp));
            end
        end
    endtask

    task automatic pack_weight_ports_exp(input integer q0_off, input integer q1_off,
                                         input integer s0_off, input integer s1_off,
                                         input integer seed, input integer K, input integer N,
                                         input integer nt_stride_q, input integer nt_stride_s,
                                         input integer e0);
        integer k_tiles;
        integer n_tiles;
        integer nt;
        integer kt;
        integer lane;
        integer kw;
        integer b;
        integer word_off_bytes;
        integer k_in_tile;
        integer k_abs;
        integer n0;
        integer n1;
        integer q0_kt;
        integer q1_kt;
        integer s0_kt;
        integer s1_kt;
        integer byte_off;
        begin
            k_tiles = div_ceil(K, TILE_K);
            n_tiles = div_ceil(N, SA_N);
            for (nt = 0; nt < n_tiles; nt = nt + 1) begin
                for (kt = 0; kt < k_tiles; kt = kt + 1) begin
                    q0_kt = q0_off + nt * nt_stride_q + kt * WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
                    q1_kt = q1_off + nt * nt_stride_q + kt * WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
                    s0_kt = s0_off + nt * nt_stride_s + kt * SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
                    s1_kt = s1_off + nt * nt_stride_s + kt * SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
                    for (lane = 0; lane < WEIGHT_COLS_PER_PORT; lane = lane + 1) begin
                        for (kw = 0; kw < TILE_K / AXI_BYTES; kw = kw + 1) begin
                            word_off_bytes = (lane * (TILE_K / AXI_BYTES) + kw) * AXI_BYTES;
                            for (b = 0; b < AXI_BYTES; b = b + 1) begin
                                k_in_tile = kw * AXI_BYTES + b;
                                k_abs = kt * TILE_K + k_in_tile;
                                n0 = nt * SA_N + lane;
                                n1 = nt * SA_N + WEIGHT_COLS_PER_PORT + lane;
                                wb_weight(0, q0_kt + word_off_bytes + b,
                                          (k_abs < K && n0 < N) ? weight_value(seed, k_abs, n0) : 0);
                                wb_weight(1, q1_kt + word_off_bytes + b,
                                          (k_abs < K && n1 < N) ? weight_value(seed, k_abs, n1) : 0);
                            end
                        end
                        for (b = 0; b < GROUPS_PER_KTILE; b = b + 1) begin
                            byte_off = (lane * GROUPS_PER_KTILE + b) * 2;
                            wb_weight(0, s0_kt + byte_off + 0, e0);
                            wb_weight(0, s0_kt + byte_off + 1, DISABLED_EXP);
                            wb_weight(1, s1_kt + byte_off + 0, e0);
                            wb_weight(1, s1_kt + byte_off + 1, DISABLED_EXP);
                        end
                    end
                end
            end
        end
    endtask

    task automatic pack_weight_ports(input integer q0_off, input integer q1_off,
                                     input integer s0_off, input integer s1_off,
                                     input integer seed, input integer K, input integer N,
                                     input integer nt_stride_q, input integer nt_stride_s);
        begin
            pack_weight_ports_exp(q0_off, q1_off, s0_off, s1_off,
                                  seed, K, N, nt_stride_q, nt_stride_s, 0);
        end
    endtask

    task automatic init_dense_task(input integer K, input integer N,
                                   input integer act_q, input integer act_s,
                                   input integer act_row_stride,
                                   input integer act_scale_stride,
                                   input integer w_q0, input integer w_q1,
                                   input integer w_s0, input integer w_s1,
                                   input integer dst,
                                   input integer out_stride,
                                   input integer nt_q_stride,
                                   input integer nt_s_stride);
        begin
            wr32(0,  32'h384d4c56);
            wr32(4,  32'd11);
            wr32(8,  32'd64);
            wr32(12, 32'd32);
            wr64(16, act_q);
            wr64(24, act_s);
            wr32(32, act_row_stride);
            wr32(36, 32'd1);
            wr32(40, K);
            wr32(44, 32'd0);
            wr64(48, 64'd0);
            wr32(56, N); wr32(60, 32'd0); wr32(64, 32'd0);
            wr32(68, 32'd0);
            wr64(72, w_q0); wr64(80, w_q1);
            wr64(120, w_s0); wr64(128, w_s1);
            wr64(168, dst);
            wr32(192, out_stride);
            wr32(204, nt_q_stride);
            wr32(208, nt_s_stride);
            wr32(212, act_scale_stride);
        end
    endtask

    task automatic init_qkv_tail_task(input integer rows, input integer K,
                                      input integer act_q, input integer act_s,
                                      input integer act_row_stride,
                                      input integer act_scale_stride,
                                      input integer q0_0, input integer q1_0,
                                      input integer s0_0, input integer s1_0,
                                      input integer q0_1, input integer q1_1,
                                      input integer s0_1, input integer s1_1,
                                      input integer q0_2, input integer q1_2,
                                      input integer s0_2, input integer s1_2,
                                      input integer dst0, input integer dst1,
                                      input integer dst2,
                                      input integer out_stride,
                                      input integer nt_q_stride,
                                      input integer nt_s_stride);
        begin
            wr32(0,  32'h384d4c56);
            wr32(4,  32'd11);
            wr32(8,  32'd65);
            wr32(12, rows);
            wr64(16, act_q);
            wr64(24, act_s);
            wr32(32, act_row_stride);
            wr32(36, 32'd3);
            wr32(40, K);
            wr32(44, 32'd0);
            wr64(48, 64'd0);
            wr32(56, 32'd32); wr32(60, 32'd32); wr32(64, 32'd32);
            wr32(68, 32'd0);
            wr64(72, q0_0); wr64(80, q1_0);
            wr64(88, q0_1); wr64(96, q1_1);
            wr64(104, q0_2); wr64(112, q1_2);
            wr64(120, s0_0); wr64(128, s1_0);
            wr64(136, s0_1); wr64(144, s1_1);
            wr64(152, s0_2); wr64(160, s1_2);
            wr64(168, dst0); wr64(176, dst1); wr64(184, dst2);
            wr32(192, out_stride); wr32(196, out_stride); wr32(200, out_stride);
            wr32(204, nt_q_stride);
            wr32(208, nt_s_stride);
            wr32(212, act_scale_stride);
        end
    endtask

    task automatic init_ffn_task(input integer task_type, input integer activation,
                                 input integer K_in, input integer K_mid,
                                 input integer N_out,
                                 input integer act_q, input integer act_s,
                                 input integer act_row_stride,
                                 input integer act_scale_stride,
                                 input integer g_q0, input integer g_q1,
                                 input integer g_s0, input integer g_s1,
                                 input integer u_q0, input integer u_q1,
                                 input integer u_s0, input integer u_s1,
                                 input integer d_q0, input integer d_q1,
                                 input integer d_s0, input integer d_s1,
                                 input integer dst,
                                 input integer out_stride,
                                 input integer nt_q_stride_in,
                                 input integer nt_s_stride_in);
        begin
            wr32(0,  32'h384d4c56);
            wr32(4,  32'd11);
            wr32(8,  task_type);
            wr32(12, 32'd32);
            wr64(16, act_q);
            wr64(24, act_s);
            wr32(32, act_row_stride);
            wr32(36, 32'd1);
            wr32(40, K_in);
            wr32(44, activation);
            wr64(48, 64'd0);
            wr32(56, N_out); wr32(60, 32'd0); wr32(64, 32'd0);
