    task automatic init_liveness_task(input [31:0] task_type);
        integer output_count;
        begin
            clear_memories();
            output_count = (task_type == 32'd65) ? 3 : 1;

            wr32(0,  32'h384d4c56);
            wr32(4,  32'd11);
            wr32(8,  task_type);
            wr32(12, 32'd32);
            wr64(16, 64'd4096);
            wr64(24, 64'd8192);
            wr32(32, 32'd128);
            wr32(36, output_count);
            wr32(40, 32'd128);
            wr32(44, (task_type == 32'd67) ? 32'd1 : 32'd0);
            wr64(48, 64'd0);
            wr32(56, 32'd32); wr32(60, 32'd32); wr32(64, 32'd32);
            wr32(68, 32'd0);
            wr32(192, 32'd128); wr32(196, 32'd128); wr32(200, 32'd128);
            wr32(204, 32'd2048);
            wr32(208, 32'd128);
            wr32(212, 32'd16);
            wr32(320, 32'd128);
            wr32(324, 32'd128);
            wr32(328, 32'd32);
        end
    endtask

    task automatic ctrl_write(input [6:0] addr, input [31:0] data);
        bit aw_done;
        bit w_done;
        begin
            aw_done = 1'b0;
            w_done = 1'b0;
            @(negedge ap_clk);
            s_axi_control_AWADDR  = addr;
            s_axi_control_AWVALID = 1'b1;
            s_axi_control_WDATA   = data;
            s_axi_control_WSTRB   = 4'hf;
            s_axi_control_WVALID  = 1'b1;
            s_axi_control_BREADY  = 1'b1;
            while (!(aw_done && w_done)) begin
                @(posedge ap_clk);
                if (s_axi_control_AWREADY) begin
                    aw_done = 1'b1;
                    s_axi_control_AWVALID = 1'b0;
                end
                if (s_axi_control_WREADY) begin
                    w_done = 1'b1;
                    s_axi_control_WVALID = 1'b0;
                end
            end
            while (!s_axi_control_BVALID) @(posedge ap_clk);
            @(negedge ap_clk);
            s_axi_control_BREADY  = 1'b0;
        end
    endtask

    task automatic ctrl_read(input [6:0] addr, output [31:0] data);
        begin
            @(negedge ap_clk);
            s_axi_control_ARADDR  = addr;
            s_axi_control_ARVALID = 1'b1;
            s_axi_control_RREADY  = 1'b1;
            while (!s_axi_control_ARREADY) @(posedge ap_clk);
            @(negedge ap_clk);
            s_axi_control_ARVALID = 1'b0;
            while (!s_axi_control_RVALID) @(posedge ap_clk);
            data = s_axi_control_RDATA;
            @(negedge ap_clk);
            s_axi_control_RREADY  = 1'b0;
        end
    endtask

    task automatic reset_dut;
        begin
            ap_rst_n = 1'b0;
            s_axi_control_AWVALID = 1'b0;
            s_axi_control_AWADDR  = '0;
            s_axi_control_WVALID  = 1'b0;
            s_axi_control_WDATA   = '0;
            s_axi_control_WSTRB   = 4'h0;
            s_axi_control_BREADY  = 1'b0;
            s_axi_control_ARVALID = 1'b0;
            s_axi_control_ARADDR  = '0;
            s_axi_control_RREADY  = 1'b0;
            repeat (20) @(posedge ap_clk);
            ap_rst_n = 1'b1;
            repeat (10) @(posedge ap_clk);
        end
    endtask

    task automatic program_and_start;
        begin
            ctrl_write(7'h10, 32'd0);
            ctrl_write(7'h14, 32'd0);
            ctrl_write(7'h1c, 32'd0);
            ctrl_write(7'h20, 32'd0);
            ctrl_write(7'h28, 32'd0);
            ctrl_write(7'h2c, 32'd0);
            ctrl_write(7'h34, 32'd0);
            ctrl_write(7'h38, 32'd0);
            ctrl_write(7'h40, 32'd0);
            ctrl_write(7'h44, 32'd0);
            ctrl_write(7'h00, 32'd1);
        end
    endtask

    task automatic wait_done(input string name);
        integer cycle;
        reg [31:0] ap_ctrl;
        begin
            for (cycle = 0; cycle < WATCHDOG_CYCLES; cycle = cycle + 1) begin
                ctrl_read(7'h00, ap_ctrl);
                if (ap_ctrl[1]) begin
                    $display("[SYS] DONE %s cycles=%0d AP_CTRL=0x%08x", name, cycle, ap_ctrl);
                    return;
                end
                if ((cycle != 0) && ((cycle % 100000) == 0)) begin
                    $display("[SYS] WAIT %s cycles=%0d AP_CTRL=0x%08x AXI act_ar=%0b/%0b act_r=%0b/%0b w0_ar=%0b/%0b w0_r=%0b/%0b w1_ar=%0b/%0b w1_r=%0b/%0b out_aw=%0b/%0b out_w=%0b/%0b out_b=%0b/%0b AXIS a=%0b/%0b w=%0b/%0b c=%0b/%0b psum=%0b/%0b PE pending=%0b drain=%0b row=%0d half=%0d",
                             name, cycle, ap_ctrl,
                             m_axi_gmem_act_ARVALID, m_axi_gmem_act_ARREADY,
                             m_axi_gmem_act_RVALID,  m_axi_gmem_act_RREADY,
                             m_axi_gmem_w0_ARVALID,  m_axi_gmem_w0_ARREADY,
                             m_axi_gmem_w0_RVALID,   m_axi_gmem_w0_RREADY,
                             m_axi_gmem_w1_ARVALID,  m_axi_gmem_w1_ARREADY,
                             m_axi_gmem_w1_RVALID,   m_axi_gmem_w1_RREADY,
                             m_axi_gmem_out_AWVALID, m_axi_gmem_out_AWREADY,
                             m_axi_gmem_out_WVALID,  m_axi_gmem_out_WREADY,
                             m_axi_gmem_out_BVALID,  m_axi_gmem_out_BREADY,
                             m_axis_a_stream_TVALID,    m_axis_a_stream_TREADY,
                             m_axis_w_stream_TVALID,    m_axis_w_stream_TREADY,
                             m_axis_ctrl_stream_TVALID, m_axis_ctrl_stream_TREADY,
                             s_axis_psum_stream_TVALID, s_axis_psum_stream_TREADY,
                             pe_array.pending_valid, pe_array.drain_phase_active,
                             pe_array.drain_row_idx, pe_array.drain_half_idx);
                end
                repeat (8) @(posedge ap_clk);
            end
            $fatal(1, "[SYS] TIMEOUT %s last_AP_CTRL=0x%08x", name, ap_ctrl);
        end
    endtask

    task automatic run_liveness_case(input [31:0] task_type, input string name);
        begin
            $display("[SYS] START liveness %s task_type=%0d", name, task_type);
            reset_dut();
            init_liveness_task(task_type);
            program_and_start();
            wait_done(name);
        end
    endtask

    task automatic compare_dense_k768(input string name);
        integer m;
        integer n;
        integer kt;
        integer k;
        integer part;
        integer total;
        integer hw;
        integer expected;
        integer err;
        begin
            err = 0;
            for (m = 0; m < 32; m = m + 1) begin
                for (n = 0; n < 32; n = n + 1) begin
                    total = 0;
                    for (kt = 0; kt < div_ceil(768, GROUP); kt = kt + 1) begin
                        part = 0;
                        for (k = kt * GROUP; k < (kt + 1) * GROUP; k = k + 1)
                            part = part + act_value(m, k) * weight_value(165, k, n);
                        total = sat_add_i32(total, shift_apply(part, act_exp_value(m, kt, 1'b1)));
                    end
                    hw = r_i32_out(m * 128 + n * 4);
                    expected = total;
                    if (hw != expected) begin
                        if (err < 8) $display("[SYS] %s mismatch row=%0d col=%0d hw=%0d expected=%0d", name, m, n, hw, expected);
                        err = err + 1;
                    end
                end
            end
            if (err != 0) $fatal(1, "[SYS] FAIL %s mismatches=%0d", name, err);
            $display("[SYS] PASS %s numeric", name);
        end
    endtask

    task automatic run_numeric_dense_k768;
        integer K;
        integer N;
        integer kt;
        integer nt_q_stride;
        integer nt_s_stride;
        begin
            K = 768;
            N = 32;
            kt = 6;
            nt_q_stride = WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES * kt;
            nt_s_stride = SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES * kt;
            $display("[SYS] START numeric REAL_VISION_DENSE_K768");
            reset_dut();
            clear_memories();
            fill_act(4096, 65536, 32, K, 768, 32, 1'b1);
            pack_weight_ports(0, 0, nt_q_stride, nt_q_stride, 165, K, N, nt_q_stride, nt_s_stride);
            init_dense_task(K, N, 4096, 65536, 768, 32,
                            0, 0, nt_q_stride, nt_q_stride,
                            0, 128, nt_q_stride, nt_s_stride);
            program_and_start();
            wait_done("REAL_VISION_DENSE_K768");
            compare_dense_k768("REAL_VISION_DENSE_K768");
        end
    endtask

    task automatic compare_qkv_tail(input string name);
        integer rows;
        integer out_stride;
        integer dst_base [0:2];
        integer seed [0:2];
        integer o;
        integer m;
        integer n;
        integer k;
        integer kt;
        integer total;
        integer hw;
        integer err;
        begin
            rows = 46;
            out_stride = 128;
            dst_base[0] = 0;
            dst_base[1] = rows * out_stride;
            dst_base[2] = rows * out_stride * 2;
            seed[0] = 201;
            seed[1] = 224;
            seed[2] = 247;
            err = 0;
            for (o = 0; o < 3; o = o + 1) begin
                for (m = 0; m < rows; m = m + 1) begin
                    for (n = 0; n < 32; n = n + 1) begin
                        total = 0;
                        for (kt = 0; kt < div_ceil(128, GROUP); kt = kt + 1) begin
                            integer part;
                            part = 0;
                            for (k = kt * GROUP; k < (kt + 1) * GROUP; k = k + 1) begin
                                part = part + act_value(m, k) * weight_value(seed[o], k, n);
                            end
                            total = sat_add_i32(total, shift_apply(part, 0));
                        end
                        hw = r_i32_out(dst_base[o] + m * out_stride + n * 4);
                        if (hw != total) begin
                            if (err < 8) $display("[SYS] %s mismatch out=%0d row=%0d col=%0d hw=%0d ref=%0d", name, o, m, n, hw, total);
                            err = err + 1;
                        end
                    end
                end
            end
            if (err != 0) $fatal(1, "[SYS] FAIL %s mismatches=%0d", name, err);
            $display("[SYS] PASS %s numeric", name);
        end
    endtask

    task automatic run_numeric_qkv_tail_m46;
        integer rows;
        integer K;
        integer out_stride;
        integer nt_q_stride;
        integer nt_s_stride;
        integer q0_0;
        integer q0_1;
        integer q0_2;
        integer s0_0;
        integer s0_1;
        integer s0_2;
        integer dst0;
        integer dst1;
        integer dst2;
        begin
            rows = 46;
            K = 128;
            out_stride = 128;
            nt_q_stride = WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
            nt_s_stride = SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
            q0_0 = 0;
            q0_1 = 4096;
            q0_2 = 8192;
            s0_0 = 16384;
            s0_1 = 16640;
            s0_2 = 16896;
            dst0 = 0;
            dst1 = rows * out_stride;
            dst2 = rows * out_stride * 2;

            $display("[SYS] START numeric QKV_TAIL_M46_NO_OVERWRITE");
            reset_dut();
            clear_memories();
            fill_act(32768, 65536, rows, K, 128, 16, 1'b0);
            pack_weight_ports(q0_0, q0_0, s0_0, s0_0, 201, K, 32, nt_q_stride, nt_s_stride);
            pack_weight_ports(q0_1, q0_1, s0_1, s0_1, 224, K, 32, nt_q_stride, nt_s_stride);
            pack_weight_ports(q0_2, q0_2, s0_2, s0_2, 247, K, 32, nt_q_stride, nt_s_stride);
            init_qkv_tail_task(rows, K,
                               32768, 65536, 128, 16,
                               q0_0, q0_0, s0_0, s0_0,
                               q0_1, q0_1, s0_1, s0_1,
                               q0_2, q0_2, s0_2, s0_2,
                               dst0, dst1, dst2,
                               out_stride, nt_q_stride, nt_s_stride);
            program_and_start();
            wait_done("QKV_TAIL_M46_NO_OVERWRITE");
            compare_qkv_tail("QKV_TAIL_M46_NO_OVERWRITE");
        end
    endtask

    task automatic compare_ffn_stride(input string name);
        integer mid_q [0:31][0:255];
        integer mid_e [0:31][0:7];
        integer fused [0:31];
        integer m;
        integer mt;
        integer c;
        integer k;
        integer n;
        integer mc;
        integer gate;
        integer up;
        integer av;
        integer max_abs;
        integer q_exp;
        integer qv;
        integer abs_v;
        integer part;
        integer total;
        integer hw;
        integer err;
        longint signed prod;
        begin
            for (m = 0; m < 32; m = m + 1) begin
                for (mt = 0; mt < 8; mt = mt + 1) begin
                    for (c = 0; c < 32; c = c + 1) begin
                        mc = mt * 32 + c;
                        gate = 0;
                        up = 0;
                        for (k = 0; k < 128; k = k + 1) begin
                            gate = gate + act_value(m, k) * weight_value(97, k, mc);
                            up = up + act_value(m, k) * weight_value(113, k, mc);
                        end
                        gate = shift_apply(gate, 0);
                        up = shift_apply(up, 0);
                        av = hard_silu(gate);
                        fused[c] = round_mul_q20(av, up);
                    end
                    max_abs = 0;
                    for (c = 0; c < 32; c = c + 1) begin
                        abs_v = (fused[c] < 0) ? -fused[c] : fused[c];
                        if (abs_v > max_abs) max_abs = abs_v;
                    end
                    q_exp = choose_pot_exp_q20(max_abs);
                    mid_e[m][mt] = q_exp;
                    for (c = 0; c < 32; c = c + 1) begin
                        mid_q[m][mt * 32 + c] = quantize_q20_exp(fused[c], q_exp);
                    end
                end
            end

            err = 0;
            for (m = 0; m < 32; m = m + 1) begin
                for (n = 0; n < 64; n = n + 1) begin
                    total = 0;
                    for (mt = 0; mt < 8; mt = mt + 1) begin
                        part = 0;
                        for (c = 0; c < 32; c = c + 1) begin
                            mc = mt * 32 + c;
                            part = part + mid_q[m][mc] * weight_value(139, mc, n);
                        end
                        total = sat_add_i32(total, shift_apply(part, mid_e[m][mt]));
                    end
                    hw = r_i32_out(m * 256 + n * 4);
                    if (hw != total) begin
                        if (err < 8) $display("[SYS] %s mismatch row=%0d col=%0d hw=%0d ref=%0d", name, m, n, hw, total);
                        err = err + 1;
                    end
                end
            end
            if (err != 0) $fatal(1, "[SYS] FAIL %s mismatches=%0d", name, err);
            $display("[SYS] PASS %s numeric", name);
        end
    endtask

    task automatic compare_ffn_generic(input string name,
                                       input integer K_in,
                                       input integer K_mid,
                                       input integer N_out,
                                       input integer gate_seed,
                                       input integer up_seed,
                                       input integer down_seed,
                                       input integer activation,
                                       input integer out_stride,
                                       input bit varied_exp,
                                       input integer gateup_w_exp,
                                       input integer down_w_exp);
        integer m;
        integer mt;
        integer c;
        integer k;
        integer kt;
        integer n;
        integer mc;
        integer gate;
        integer gate_part;
        integer up;
        integer up_part;
        integer av;
        integer max_abs;
        integer q_exp;
        integer qv;
        integer abs_v;
        integer part;
        integer total;
        integer hw;
        integer err;
        integer groups_mid;
        longint signed prod;
        begin
            groups_mid = div_ceil(K_mid, TILE_K);
            for (m = 0; m < 32; m = m + 1) begin
                for (mt = 0; mt < groups_mid; mt = mt + 1) begin
                    for (c = 0; c < TILE_K; c = c + 1) begin
                        mc = mt * TILE_K + c;
                        if (mc < K_mid) begin
                            gate = 0;
                            up = 0;
                            for (kt = 0; kt < div_ceil(K_in, TILE_K); kt = kt + 1) begin
                                gate_part = 0;
                                up_part = 0;
                                for (k = kt * TILE_K; k < (kt + 1) * TILE_K; k = k + 1) begin
                                    if (k < K_in) begin
                                        gate_part = gate_part + act_value(m, k) * weight_value(gate_seed, k, mc);
                                        up_part = up_part + act_value(m, k) * weight_value(up_seed, k, mc);
                                    end
                                end
                                gate = sat_add_i32(gate, shift_apply(gate_part, act_exp_value(m, kt * GROUPS_PER_KTILE, varied_exp) + gateup_w_exp));
                                up = sat_add_i32(up, shift_apply(up_part, act_exp_value(m, kt * GROUPS_PER_KTILE, varied_exp) + gateup_w_exp));
                            end
                            av = (activation == 1) ? hard_gelu(gate) : hard_silu(gate);
                            ffn_ref_mid_q[m][mc] = round_mul_q20(av, up);
                        end else begin
                            ffn_ref_mid_q[m][mc] = 0;
                        end
                    end
                    max_abs = 0;
                    for (c = 0; c < TILE_K; c = c + 1) begin
                        mc = mt * TILE_K + c;
                        abs_v = (ffn_ref_mid_q[m][mc] < 0) ? -ffn_ref_mid_q[m][mc] : ffn_ref_mid_q[m][mc];
                        if (abs_v > max_abs) max_abs = abs_v;
                    end
                    q_exp = choose_pot_exp_q20(max_abs);
                    ffn_ref_mid_e[m][mt] = q_exp;
                    for (c = 0; c < TILE_K; c = c + 1) begin
                        mc = mt * TILE_K + c;
                        ffn_ref_mid_q[m][mc] = quantize_q20_exp(ffn_ref_mid_q[m][mc], q_exp);
                    end
                end
            end

            err = 0;
            for (m = 0; m < 32; m = m + 1) begin
                for (n = 0; n < N_out; n = n + 1) begin
                    total = 0;
                    for (mt = 0; mt < groups_mid; mt = mt + 1) begin
                        part = 0;
                        for (c = 0; c < TILE_K; c = c + 1) begin
                            mc = mt * TILE_K + c;
                            if (mc < K_mid) begin
                                part = part + ffn_ref_mid_q[m][mc] * weight_value(down_seed, mc, n);
                            end
                        end
                        total = sat_add_i32(total, shift_apply(part, ffn_ref_mid_e[m][mt] + down_w_exp));
                    end
                    hw = r_i32_out(m * out_stride + n * 4);
                    if (hw != total) begin
                        if (err < 8) $display("[SYS] %s mismatch row=%0d col=%0d hw=%0d ref=%0d", name, m, n, hw, total);
                        err = err + 1;
                    end
                end
            end
            if (err != 0) $fatal(1, "[SYS] FAIL %s mismatches=%0d", name, err);
            $display("[SYS] PASS %s numeric", name);
        end
    endtask

    task automatic run_numeric_ffn_stride;
        integer nt_q_stride_in;
        integer nt_s_stride_in;
        integer nt_q_stride_down;
        integer nt_s_stride_down;
        integer g_q;
        integer g_s;
        integer u_q;
        integer u_s;
        integer d_q;
        integer d_s;
        begin
            nt_q_stride_in = WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
            nt_s_stride_in = SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
            nt_q_stride_down = WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES * 2;
            nt_s_stride_down = SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES * 2;
            g_q = 0;
            g_s = 8 * nt_q_stride_in;
            u_q = g_s + 8 * nt_s_stride_in;
            u_s = u_q + 8 * nt_q_stride_in;
            d_q = u_s + 8 * nt_s_stride_in;
            d_s = d_q + 2 * nt_q_stride_down;

            $display("[SYS] START numeric FFN_DOWN_STRIDE_KMID256_KOUT64");
            reset_dut();
            clear_memories();
            fill_act(4096, 65536, 32, 128, 128, 16, 1'b0);
            pack_weight_ports_exp(g_q, g_q, g_s, g_s, 97, 128, 256, nt_q_stride_in, nt_s_stride_in, -8);
            pack_weight_ports_exp(u_q, u_q, u_s, u_s, 113, 128, 256, nt_q_stride_in, nt_s_stride_in, -8);
            pack_weight_ports_exp(d_q, d_q, d_s, d_s, 139, 256, 64, nt_q_stride_down, nt_s_stride_down, -4);
            init_ffn_task(66, 0, 128, 256, 64,
                          4096, 65536, 128, 16,
                          g_q, g_q, g_s, g_s,
                          u_q, u_q, u_s, u_s,
                          d_q, d_q, d_s, d_s,
                          0, 256,
                          nt_q_stride_in, nt_s_stride_in);
            program_and_start();
            wait_done("FFN_DOWN_STRIDE_KMID256_KOUT64");
            compare_ffn_generic("FFN_DOWN_STRIDE_KMID256_KOUT64", 128, 256, 64, 97, 113, 139, 0, 256, 1'b0, -8, -4);
        end
    endtask

    task automatic run_numeric_ffn_real_head(input string name,
                                             input integer task_type,
                                             input integer activation,
                                             input integer K_in,
                                             input integer K_mid,
                                             input integer N_out,
                                             input integer gate_seed,
                                             input integer up_seed,
                                             input integer down_seed,
                                             input bit varied_exp);
        integer kt_in;
        integer kt_mid;
        integer nt_mid;
        integer nt_out;
        integer act_scale_stride;
        integer nt_q_stride_in;
        integer nt_s_stride_in;
        integer nt_q_stride_down;
        integer nt_s_stride_down;
        integer g_q;
        integer g_s;
        integer u_q;
        integer u_s;
        integer d_q;
        integer d_s;
        integer out_stride;
        begin
            kt_in = div_ceil(K_in, TILE_K);
            kt_mid = div_ceil(K_mid, TILE_K);
            nt_mid = div_ceil(K_mid, SA_N);
            nt_out = div_ceil(N_out, SA_N);
            act_scale_stride = ((div_ceil(K_in, GROUP) + 15) / 16) * 16;
            nt_q_stride_in = WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES * kt_in;
            nt_s_stride_in = SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES * kt_in;
            nt_q_stride_down = WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES * kt_mid;
            nt_s_stride_down = SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES * kt_mid;
            g_q = 0;
            g_s = g_q + nt_mid * nt_q_stride_in;
            u_q = g_s + nt_mid * nt_s_stride_in;
            u_s = u_q + nt_mid * nt_q_stride_in;
            d_q = u_s + nt_mid * nt_s_stride_in;
            d_s = d_q + nt_out * nt_q_stride_down;
            out_stride = N_out * 4;

            $display("[SYS] START numeric %s", name);
            reset_dut();
            clear_memories();
            fill_act(4096, 65536, 32, K_in, K_in, act_scale_stride, varied_exp);
            // These full-shape FFN cases are structural RTL smoke tests. Keep
            // the real K/stride/tile layout, but use modest synthetic scales so
            // the checker does not turn into an INT32 saturation edge-case test.
            // Saturation behavior is not what this gate is trying to qualify.
            pack_weight_ports_exp(g_q, g_q, g_s, g_s, gate_seed, K_in, K_mid, nt_q_stride_in, nt_s_stride_in, -8);
            pack_weight_ports_exp(u_q, u_q, u_s, u_s, up_seed, K_in, K_mid, nt_q_stride_in, nt_s_stride_in, -8);
            pack_weight_ports_exp(d_q, d_q, d_s, d_s, down_seed, K_mid, N_out, nt_q_stride_down, nt_s_stride_down, -4);
            init_ffn_task(task_type, activation, K_in, K_mid, N_out,
                          4096, 65536, K_in, act_scale_stride,
                          g_q, g_q, g_s, g_s,
                          u_q, u_q, u_s, u_s,
                          d_q, d_q, d_s, d_s,
                          0, out_stride,
                          nt_q_stride_in, nt_s_stride_in);
            program_and_start();
            wait_done(name);
            compare_ffn_generic(name, K_in, K_mid, N_out, gate_seed, up_seed, down_seed, activation, out_stride, varied_exp, -8, -4);
        end
    endtask

    initial begin
        run_liveness_case(32'd64, "GEMM_DENSE_O");
        run_liveness_case(32'd65, "GEMM_FUSED_QKV");
        run_liveness_case(32'd66, "GEMM_FUSED_TEXT_FFN");
        run_liveness_case(32'd67, "GEMM_FUSED_VISION_FFN");
        $display("[SYS] PASS: ap_done liveness");

        run_numeric_dense_k768();
        run_numeric_qkv_tail_m46();
        run_numeric_ffn_stride();
        $display("[SYS] PASS: vlm_engine_v4 RTL + pe_array_v4 RTL liveness and numeric smoke");
        $finish;
    end
endmodule
